def email_host(value):
    if not isinstance(value, str):
        raise ValueError("address must be text")
    local, sep, domain = value.strip().partition("@")
    if not sep or not local or not domain or "@" in domain or any(c.isspace() for c in local + domain):
        raise ValueError("invalid address")
    return domain.casefold()

def merge_windows(windows):
    nonempty = []
    for start, end in windows:
        if type(start) is not int or type(end) is not int or start > end:
            raise ValueError("invalid interval")
        if start < end:
            nonempty.append((start, end))
    merged = []
    for start, end in sorted(nonempty):
        if merged and start <= merged[-1][1]:
            merged[-1] = (merged[-1][0], max(end, merged[-1][1]))
        else:
            merged.append((start, end))
    return merged

def parse_flags(text):
    if not isinstance(text, str):
        raise ValueError("flags must be text")
    parsed = {}
    for part in text.split(";"):
        if not part.strip():
            continue
        key, sep, value = part.partition("=")
        if not sep or not key.strip():
            raise ValueError("invalid flag")
        parsed[key.strip().casefold()] = value.strip()
    return parsed
